import{_ as t,o,c as l,a2 as i}from"./chunks/framework.Crpw6aS5.js";const q=JSON.parse('{"title":"IBM（International Business Machines Corporation）","description":"","frontmatter":{},"headers":[],"relativePath":"03_companies/IBM.md","filePath":"03_companies/IBM.md"}'),e={name:"03_companies/IBM.md"};function r(n,a,h,s,d,u){return o(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="ibm-international-business-machines-corporation" tabindex="-1">IBM（International Business Machines Corporation） <a class="header-anchor" href="#ibm-international-business-machines-corporation" aria-label="Permalink to &quot;IBM（International Business Machines Corporation）&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>内容</th></tr></thead><tbody><tr><td>英文名</td><td>International Business Machines Corporation</td></tr><tr><td>行业</td><td>科技 / IT 服务</td></tr><tr><td>成立年份</td><td>1911年</td></tr><tr><td>总部</td><td>纽约州阿蒙克</td></tr><tr><td>伯克希尔持股</td><td>最高约 7.8%，2018年几乎全部清仓</td></tr><tr><td>首次买入</td><td>2011年</td></tr><tr><td>清仓时间</td><td>2018年</td></tr><tr><td>持仓时间</td><td>约 7 年</td></tr></tbody></table><h2 id="核心业务" tabindex="-1">核心业务 <a class="header-anchor" href="#核心业务" aria-label="Permalink to &quot;核心业务&quot;">​</a></h2><p>IBM 是全球最早的科技巨头之一，历史上业务涵盖：</p><ul><li><strong>硬件</strong>：大型计算机（Mainframe）、服务器、存储设备</li><li><strong>软件</strong>：中间件、企业软件（Db2、Cognos、Tivoli 等）</li><li><strong>IT 服务</strong>：咨询、系统集成、外包服务</li><li><strong>云计算</strong>：2010年代转型期间重点发展的方向</li><li><strong>人工智能</strong>：Watson 认知计算平台</li></ul><p>IBM 曾是道琼斯工业平均指数中历史最悠久的成分股（1916年加入，2012年被剔除），见证了整个科技产业的发展变迁。</p><h2 id="与巴菲特的关系" tabindex="-1">与巴菲特的关系 <a class="header-anchor" href="#与巴菲特的关系" aria-label="Permalink to &quot;与巴菲特的关系&quot;">​</a></h2><h3 id="首次大规模科技股投资-2011年" tabindex="-1">首次大规模科技股投资（2011年） <a class="header-anchor" href="#首次大规模科技股投资-2011年" aria-label="Permalink to &quot;首次大规模科技股投资（2011年）&quot;">​</a></h3><p>2011年，巴菲特宣布伯克希尔买入约 6400 万股 IBM 股票，价值约 107-114 亿美元（约占伯克希尔当时股票组合的 7%），这是巴菲特<strong>首次大规模投资科技股</strong>，打破了其长期回避科技股的原则。</p><p><strong>投资理由：</strong></p><ul><li>IBM 拥有强大的护城河——企业级 IT 服务的转换成本极高</li><li>IBM 的商业模式类似咨询公司，有定价权</li><li>看好 IBM 向高利润服务业务转型</li><li>转型期间股价处于相对低位</li></ul><h3 id="承认判断失误-2017-2018年" tabindex="-1">承认判断失误（2017-2018年） <a class="header-anchor" href="#承认判断失误-2017-2018年" aria-label="Permalink to &quot;承认判断失误（2017-2018年）&quot;">​</a></h3><p>2017年，巴菲特开始减持 IBM，并在 2018 年初的股东信中公开承认：</p><blockquote><p>&quot;我错了。IBM 是一家强大的公司，但它面临的竞争对手比我买入时想象的更强大。&quot;</p></blockquote><p><strong>主要失误：</strong></p><ol><li><strong>云计算竞争失利</strong>：亚马逊 AWS、微软 Azure 的崛起侵蚀了 IBM 的企业 IT 服务市场</li><li><strong>转型不及预期</strong>：IBM 的云计算转型速度落后于竞争对手</li><li><strong>护城河被低估</strong>：科技行业的变化速度远超预期，&quot;转换成本&quot;护城河不如想象中坚固</li><li><strong>竞争格局恶化</strong>：科技行业竞争加剧，传统 IT 服务商普遍承压</li></ol><h3 id="最终清仓" tabindex="-1">最终清仓 <a class="header-anchor" href="#最终清仓" aria-label="Permalink to &quot;最终清仓&quot;">​</a></h3><p>2018年，伯克希尔几乎清仓了全部 IBM 股票，标志着巴菲特罕见的投资失败案例。</p><h2 id="核心竞争优势" tabindex="-1">核心竞争优势 <a class="header-anchor" href="#核心竞争优势" aria-label="Permalink to &quot;核心竞争优势&quot;">​</a></h2><h3 id="_1-高转换成本-曾经" tabindex="-1">1. 高转换成本（曾经） <a class="header-anchor" href="#_1-高转换成本-曾经" aria-label="Permalink to &quot;1. 高转换成本（曾经）&quot;">​</a></h3><ul><li>企业 IT 系统深度嵌入业务流程</li><li>更换供应商的成本和风险极高</li><li>理论上形成强大护城河</li></ul><h3 id="_2-品牌与技术积累" tabindex="-1">2. 品牌与技术积累 <a class="header-anchor" href="#_2-品牌与技术积累" aria-label="Permalink to &quot;2. 品牌与技术积累&quot;">​</a></h3><ul><li>近百年技术积累与专利组合</li><li>在大型机和关键任务系统领域占据主导地位</li><li>全球政府和大型企业客户基础</li></ul><h3 id="_3-服务与咨询能力" tabindex="-1">3. 服务与咨询能力 <a class="header-anchor" href="#_3-服务与咨询能力" aria-label="Permalink to &quot;3. 服务与咨询能力&quot;">​</a></h3><ul><li>企业级 IT 咨询的专业团队</li><li>深入理解客户业务流程</li></ul><h2 id="投资教训" tabindex="-1">投资教训 <a class="header-anchor" href="#投资教训" aria-label="Permalink to &quot;投资教训&quot;">​</a></h2><h3 id="_1-科技股需要特别谨慎" tabindex="-1">1. 科技股需要特别谨慎 <a class="header-anchor" href="#_1-科技股需要特别谨慎" aria-label="Permalink to &quot;1. 科技股需要特别谨慎&quot;">​</a></h3><ul><li>科技行业变化速度极快</li><li>今天的护城河可能明天就被颠覆</li><li>巴菲特在 IBM 之前长期回避科技股不是没有道理</li></ul><h3 id="_2-转换成本-护城河需要动态评估" tabindex="-1">2. &quot;转换成本&quot;护城河需要动态评估 <a class="header-anchor" href="#_2-转换成本-护城河需要动态评估" aria-label="Permalink to &quot;2. &quot;转换成本&quot;护城河需要动态评估&quot;">​</a></h3><ul><li>即使有高转换成本，竞争依然可以从其他维度突破</li><li>亚马逊 AWS 证明了&quot;重起炉灶&quot;而非&quot;替换 IBM&quot;的可能性</li></ul><h3 id="_3-承认错误的重要性" tabindex="-1">3. 承认错误的重要性 <a class="header-anchor" href="#_3-承认错误的重要性" aria-label="Permalink to &quot;3. 承认错误的重要性&quot;">​</a></h3><ul><li>巴菲特果断止损，而非死守错误仓位</li><li>这是保护资本的重要纪律</li></ul><h3 id="_4-能力圈原则" tabindex="-1">4. 能力圈原则 <a class="header-anchor" href="#_4-能力圈原则" aria-label="Permalink to &quot;4. 能力圈原则&quot;">​</a></h3><ul><li>IBM 是巴菲特少有的&quot;越圈&quot;尝试</li><li>结果证明了他在传统消费股上的能力未必适用于科技股</li></ul><h2 id="巴菲特评价摘录" tabindex="-1">巴菲特评价摘录 <a class="header-anchor" href="#巴菲特评价摘录" aria-label="Permalink to &quot;巴菲特评价摘录&quot;">​</a></h2><blockquote><p>&quot;IBM 不是我的typical 类型（能力圈内）。但我看好它的护城河。&quot; —— 2011年</p></blockquote><blockquote><p>&quot;六年前我买入 IBM 时，我犯了一个大错。六年后，情况更加证明了这一点。&quot; —— 2017年</p></blockquote><blockquote><p>&quot;我不应该买 IBM。你可能想知道我现在是否还持有苹果——是的，我会的。但 IBM，我没有那种确定性。&quot; —— 2017年 CNBC 采访</p></blockquote><blockquote><p>&quot;在 IBM 上，我低估了竞争的激烈程度。&quot; —— 2018年股东信</p></blockquote><h2 id="在股东信中的年份" tabindex="-1">在股东信中的年份 <a class="header-anchor" href="#在股东信中的年份" aria-label="Permalink to &quot;在股东信中的年份&quot;">​</a></h2><p>2011, 2012, 2013, 2014, 2015, 2016, 2017, 2018</p><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔哈撒韦</a> - 投资主体</li><li><a href="./苹果.html">苹果</a> - IBM 清仓后买入的科技股替代</li></ul><hr><p><em>最后更新：2026-04-12</em></p>',46)])])}const b=t(e,[["render",r]]);export{q as __pageData,b as default};
